      value = rt.binary('-', rt.f(1), value, 1, 'float')
    end
    g['fragColor'].replace((rt.construct(4, rt.construct(3, value), rt.f(1))).map { |c| rt.f32(c) })
  end
  main__void.call
  c = g['fragColor']
  out[0] = rt.f32(c[0]); out[1] = rt.f32(c[1]); out[2] = rt.f32(c[2]); out[3] = rt.f32(c[3])
end
